{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const dbPath = process.env.DB_PATH || path.join(path.dirname(fileURLToPath(import.meta.url)), 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);

const page = await readFile(new URL('./index.html', import.meta.url));

function sendJson(res, status, data) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/health') {
    return sendJson(res, 200, { status: 'ok' });
  }
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    return sendJson(res, 200, db.prepare('SELECT id, name FROM projects ORDER BY id').all());
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const name = typeof data.name === 'string' ? data.name.trim() : '';
    if (!name) return sendJson(res, 400, { error: 'Project name is required' });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return sendJson(res, 201, { id: Number(result.lastInsertRowid), name });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (req.method === 'GET' && projectMatch) {
    const project = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    return project ? sendJson(res, 200, project) : sendJson(res, 404, { error: 'Project not found' });
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return res.end(page);
  }
  sendJson(res, 404, { error: 'Not found' });
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #172033; background: #f5f7fb; }
    * { box-sizing: border-box; }
    body { margin: 0; }
    main { width: min(720px, calc(100% - 32px)); margin: 56px auto; }
    h1 { margin: 0 0 24px; font-size: 2rem; }
    form, .project-row { display: flex; align-items: center; gap: 12px; }
    form { margin-bottom: 16px; }
    label { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
    input { flex: 1; min-width: 0; padding: 11px 12px; border: 1px solid #aab4c4; border-radius: 6px; font: inherit; background: white; }
    button { padding: 10px 14px; border: 0; border-radius: 6px; font: inherit; font-weight: 600; color: white; background: #2459c4; cursor: pointer; }
    button:hover { background: #19479f; }
    button:focus-visible, input:focus-visible { outline: 3px solid #90b4ff; outline-offset: 2px; }
    #alert { min-height: 1.5em; color: #b42318; }
    #projects { display: grid; gap: 10px; }
    .project-row { justify-content: space-between; padding: 14px 16px; border: 1px solid #d9dfeb; border-radius: 8px; background: white; }
    .project-name { overflow-wrap: anywhere; }
    #detail { margin-top: 22px; }
    #detail h1 { margin-top: 22px; }
    @media (max-width: 480px) { form { align-items: stretch; flex-direction: column; } }
  </style>
</head>
<body>
  <main>
    <section id="list-view" hidden>
      <h1>Workboard</h1>
      <form id="create-form" novalidate>
        <label for="project-name">Project name</label>
        <input id="project-name" name="name" type="text" aria-label="Project name">
        <button type="submit">Create project</button>
      </form>
      <div id="alert" role="alert" aria-live="polite"></div>
      <div id="projects"></div>
    </section>
    <section id="detail" hidden>
      <button id="back" type="button">Projects</button>
      <h1 id="detail-name"></h1>
    </section>
  </main>
  <script>
    const listView = document.querySelector('#list-view');
    const detail = document.querySelector('#detail');
    const projects = document.querySelector('#projects');
    const alertBox = document.querySelector('#alert');

    async function loadProjects() {
      const response = await fetch('/api/projects');
      return response.json();
    }

    async function showList() {
      listView.hidden = false;
      detail.hidden = true;
      const items = await loadProjects();
      projects.replaceChildren(...items.map(project => {
        const row = document.createElement('div');
        row.className = 'project-row';
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.className = 'project-name';
        name.textContent = project.name;
        const open = document.createElement('button');
        open.type = 'button';
        open.textContent = 'Open project';
        open.addEventListener('click', () => navigate(`/projects/${project.id}`));
        row.append(name, open);
        return row;
      }));
    }

    async function showProject(id) {
      listView.hidden = true;
      detail.hidden = false;
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) {
        history.replaceState({}, '', '/');
        await showList();
        return;
      }
      const project = await response.json();
      document.querySelector('#detail-name').textContent = project.name;
    }

    function navigate(path) {
      history.pushState({}, '', path);
      render();
    }

    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) await showProject(match[1]);
      else await showList();
    }

    document.querySelector('#create-form').addEventListener('submit', async event => {
      event.preventDefault();
      const input = document.querySelector('#project-name');
      const name = input.value.trim();
      if (!name) {
        alertBox.textContent = 'Project name is required';
        input.focus();
        return;
      }
      const response = await fetch('/api/projects', {
        method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
      });
      if (response.ok) {
        input.value = '';
        alertBox.textContent = '';
        await showList();
      }
    });
    document.querySelector('#back').addEventListener('click', () => navigate('/'));
    window.addEventListener('popstate', render);
    render();
  </script>
</body>
</html>
